1	import { randomBytes } from "node:crypto";
2	
3	/** A UUIDv7: time-ordered, used for all platform IDs. */
4	export function newId(now: Date = new Date()): string {
5	  const bytes = randomBytes(16);
6	  const ms = BigInt(now.getTime());
7	  for (let i = 0; i < 6; i++) {
8	    bytes[i] = Number((ms >> BigInt(8 * (5 - i))) & 0xffn);
9	  }
10	  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x70;
11	  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;
12	  const hex = bytes.toString("hex");
